    private void btnIniciarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnIniciarActionPerformed
        // TODO add your handling code here:
        recibir();
    }//GEN-LAST:event_btnIniciarActionPerformed

    private void recibir(){
        String user = txtUsuario.getText();
        String con = String.valueOf(pwdContra.getText());
        System.out.println("Usuario" + user);
        System.out.println("Contraseña" + con );
        String usuario2 = "chavez";
        String contraseña = "cacorraz";
                
        if(user.length()==0 || con.length()==0){
            JOptionPane.showMessageDialog(null, "Error Campo vacio", "ERROR" , JOptionPane.ERROR_MESSAGE);
        }else{
            if(user.equals(usuario2) && con.equals(contraseña)){
                JOptionPane.showMessageDialog(null, "hola"+ user+ "\nBienvenido");
            }
            JOptionPane.showMessageDialog(null, "Usuario: "+user+"\nContraseña: "+con);

        }
    }
